const envelope = $json || {};
const body = envelope.body || envelope;
const content = body.content || body.message || body.data?.content || {};
const contact = body.contact || body.sender || body.data?.contact || {};

const doc =
  content.document ||
  content.documentMessage ||
  body.document ||
  body.documentMessage ||
  content.image ||
  body.image ||
  null;

const rawMsg =
  content.text ||
  content.body ||
  content.caption ||
  body.message?.text ||
  body.message ||
  '';

const chatInput = String(rawMsg || '').trim();

let phone = String(
  contact.number ||
  contact.phone ||
  contact.id?.user ||
  body.phone ||
  body.sessionId ||
  ''
).replace(/\D/g, '');

if (!phone) return [{ json: { ignore: true } }];
if (!phone.startsWith('55')) phone = '55' + phone;

const mediaBase64 =
  content.media ||
  content.base64 ||
  doc?.base64 ||
  doc?.data ||
  body.mediaBase64 ||
  body.document?.base64 ||
  body.documentMessage?.base64 ||
  null;

const mimetype = String(
  content.mimetype ||
  content.mimeType ||
  content.mime_type ||
  doc?.mimetype ||
  doc?.mimeType ||
  doc?.mime_type ||
  body.mimetype ||
  ''
).toLowerCase();

const fileName =
  content.fileName ||
  content.filename ||
  content.file_name ||
  doc?.fileName ||
  doc?.filename ||
  doc?.file_name ||
  body.fileName ||
  body.file_name ||
  null;

const hasAny = !!chatInput || !!mediaBase64 || !!mimetype || !!fileName;
if (!hasAny) return [{ json: { ignore: true } }];

return [{
  json: {
    ignore: false,
    phone,
    sessionId: phone,
    chatInput,
    mediaBase64,
    mimetype,
    fileName,
    rawPayload: body,
    history: []
  }
}];

const item = $input.first().json || {};
const p = item.mychatPayload || {};
const number = String(p.number || item.phone || '').replace(/\D/g, '');
const msg = String(p.body || item.message || '').replace(/[\r\n]+/g, ' ').trim();
if (!number || !msg) throw new Error('API nao retornou dados para MyChat');

return [{ json: {
  number,
  body: msg,
  externalKey: p.externalKey || `lead_${number}`,
  isClosed: p.isClosed === true
} }];
